/*
 * Zephyr ADC example – hardware oversampling (16 samples)
 *
 * Target board: nrf52840dk/nrf52840
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>

/* ADC device alias defined in the devicetree */
const struct device *adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));

int main(void)
{
    int ret;

    /* Check that the ADC device is ready */
    if (!device_is_ready(adc_dev)) {
        printk("ADC device not ready\n");
        return -ENODEV;
    }

    /* Configure ADC channel 0 */
    struct adc_channel_cfg channel_cfg = {
        .gain              = ADC_GAIN_1,
        .reference         = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id        = 0,
    };

    ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret < 0) {
        printk("adc_channel_setup failed (%d)\n", ret);
        return ret;
    }

    /* Buffer for one 12‑bit sample */
    static int16_t sample_buf[1];

    /* ADC sequence configuration – 16‑sample hardware averaging */
    struct adc_sequence seq = {
        .channels      = BIT(0),                     /* channel 0 */
        .buffer        = sample_buf,
        .buffer_size   = sizeof(sample_buf),
        .resolution    = 12,                         /* 12‑bit resolution */
        .oversampling  = 4,                          /* 2^4 = 16 samples */
    };

    while (1) {
        ret = adc_read(adc_dev, &seq);
        if (ret == 0) {
            printk("Raw sample: %d\n", sample_buf[0]);
